describe('Date Picker - Past Date Prevention for Future Bookings', () => {
  beforeEach(() => {
    cy.visit('/booking');
  });

  it('should prevent selecting past dates and only allow future dates', () => {
    // Verify date picker is visible
    cy.get('[data-testid="date-picker"]').should('be.visible');

    // Attempt to select a past date (e.g., yesterday)
    cy.get('[data-testid="date-picker"]').click();
    cy.get('[data-testid="date-picker"]').should('be.visible');

    // Verify past dates are disabled
    cy.get('[data-testid="date-picker"]').find('[data-testid="date-cell"]').first().should('have.attr', 'disabled');

    // Attempt to click a disabled past date cell
    cy.get('[data-testid="date-picker"]').find('[data-testid="date-cell"]').first().click({ force: true });

    // Verify the date was not selected
    cy.get('[data-testid="selected-date"]').should('not. exist');

    // Select a future date
    cy.get('[data-testid="date-picker"]').click();
    cy.get('[data-testid="date-picker"]').find('[data-testid="date-cell"]').eq(5).click();

    // Verify future date is selected
    cy.get('[data-testid="selected-date"]').should('contain', '2024-11-20');

    // Verify date picker closes after selection
    cy.get('[data-testid="date-picker"]').should('not. be.visible');

    // Verify booking form is enabled for submission
    cy.get('[data-testid="submit-booking-btn"]').should('not. be').disabled();
  });

  it('should display error message when user attempts to submit with past date', () => {
    // Select a past date
    cy.get('[data-testid="date-picker"]').click();
    cy.get('[data-testid="date-picker"]').find('[data-testid="date-cell"]').first().click();

    // Verify past date is selected
    cy.get('[data-testid="selected-date"]').should('contain', '2023-01-01');

    // Attempt to submit the form
    cy.get('[data-testid="submit-booking-btn"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Cannot book past dates');

    // Verify form is not submitted
    cy.url().should('include', '/booking');

    // Verify date field is still populated with the invalid date
    cy.get('[data-testid="selected-date"]').should('contain', '2023-01-01');

    // Clear the invalid date and select a valid future date
    cy.get('[data-testid="selected-date"]').clear();
    cy.get('[data-testid="date-picker"]').click();
    cy.get('[data-testid="date-picker"]').find('[data-testid="date-cell"]').eq(10).click();

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not. exist');

    // Verify form is now ready for submission
    cy.get('[data-testid="submit-booking-btn"]').should('not. be').disabled();
  });
});
